package br.com.brindespro.security;
import org.springframework.boot.CommandLineRunner;import org.springframework.core.env.Environment;import org.springframework.stereotype.Component;
@Component public class AdminBootstrap implements CommandLineRunner {private final AdminUserRepository users;private final PasswordEncoderHolder encoder;private final Environment env;public AdminBootstrap(AdminUserRepository users,org.springframework.security.crypto.password.PasswordEncoder encoder,Environment env){this.users=users;this.encoder=new PasswordEncoderHolder(encoder);this.env=env;}private record PasswordEncoderHolder(org.springframework.security.crypto.password.PasswordEncoder value){}@Override public void run(String...args){String email=env.getProperty("ADMIN_EMAIL");String password=env.getProperty("ADMIN_PASSWORD");if(email!=null&&password!=null&&!email.isBlank()&&password.length()>=16&&users.findByEmail(email).isEmpty())users.save(new AdminUser(email,encoder.value().encode(password),"Administrador"));}}
